INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(27401, '1 Corinthians 8:7', '1 Corinthians', 8, 7, '&nbsp;خو هر چا ته دا عِلم نشته بلکې د ځينو خو اوس هم د بُت پرستۍ عادت دے، هغوئ اوس هم هغه غوښه د بُت قربانى ګڼى او خورى يې او د هغوئ ضمير کمزورے او پليت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27402, '1 Corinthians 8:8', '1 Corinthians', 8, 8, '&nbsp;خوراک مونږ د خُدائ پاک سره نزدې کولے نۀ شى. کۀ وې يې نۀ خورو نو مونږ ته يې څۀ نقصان نشته او کۀ وې يې خورو نو څۀ فائده هم نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27403, '1 Corinthians 8:9', '1 Corinthians', 8, 9, '&nbsp;خو خيال کوئ، چې ستاسو آزادى د کمزورو دپاره د تيندک باعث نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27404, '1 Corinthians 8:10', '1 Corinthians', 8, 10, '&nbsp;ځکه کۀ نور خلق ستا په شان د عِلم خاوند په بُت‌خانه کښې په خوراک ووينى نو ولې د هغوئ کمزورے ضمير به زړَور نۀ شى چې د بُتانو د قربانۍ غوښه وخورى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27405, '1 Corinthians 8:11', '1 Corinthians', 8, 11, '&nbsp;نو ستا د عِلم په وجه به هغه کمزورى ايمانداران چې د چا دپاره چې مسيح مړ شو، هغه به هلاک شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27406, '1 Corinthians 8:12', '1 Corinthians', 8, 12, '&nbsp;خو کله چې تاسو د نورو ايماندارانو په خلاف ګناه کوئ او د هغوئ کمزورے ضمير زخمى کوئ نو تاسو د مسيح خلاف ګناه کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27407, '1 Corinthians 8:13', '1 Corinthians', 8, 13, '&nbsp;په دې وجه کۀ زما د خوراک په وجه زما ورور يا خور تيندک خورى نو زۀ به هيڅکله هم غوښه ونۀ خورم نو چې زۀ د هغوئ دپاره د تيندک سبب ونۀ ګرځم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27408, '1 Corinthians 9:1', '1 Corinthians', 9, 1, '&nbsp;ولې زۀ آزاد نۀ يم څۀ؟ ولې زۀ رسول نۀ يم څۀ؟ ولې ما عيسىٰ چې زمونږ مالِک دے نۀ دے ليدلے څۀ؟ ولې تاسو په مالِک کښې زما د خِدمت مېوه نۀ يئ څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27409, '1 Corinthians 9:2', '1 Corinthians', 9, 2, '&nbsp;کۀ زۀ د نورو دپاره رسول نۀ يم نو کم از کم ستاسو دپاره خو يم ځکه چې تاسو په مالِک کښې زما د رسالت مهر يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27410, '1 Corinthians 9:3', '1 Corinthians', 9, 3, '&nbsp;څوک چې زما آزمېښت کوى دا د هغوئ په وړاندې زما دفاع ده،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27411, '1 Corinthians 9:4', '1 Corinthians', 9, 4, '&nbsp;ولې مونږ ته د خپل خوراک څښاک حق نشته څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27412, '1 Corinthians 9:5', '1 Corinthians', 9, 5, '&nbsp;ولې مونږ ته دا حق نشته چې ايمانداره ښځه په نِکاح کړُو او ځان سره يې کړو لکه څنګه چې نور رسولان او د مالِک وروڼه او کائفس کوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27413, '1 Corinthians 9:6', '1 Corinthians', 9, 6, '&nbsp;يا يواځې زۀ او برنباس د ژوند تېرولو دپاره په خوارۍ مزدورۍ پړ يُو څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27414, '1 Corinthians 9:7', '1 Corinthians', 9, 7, '&nbsp;ولې تر اوسه چا په خپله خرچه د فوج خِدمت کړے دے؟ څوک داسې دے چې د انګورو باغ وکَرى او مېوه يې نۀ خورى؟ يا څوک داسې دى چې رمه څروى او د هغې پئ نۀ څښى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27415, '1 Corinthians 9:8', '1 Corinthians', 9, 8, '&nbsp;ولې زۀ دا خبرې د بنى آدم د خيال نه کوم؟ ولې شريعت هم داسې نۀ وائى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27416, '1 Corinthians 9:9', '1 Corinthians', 9, 9, '&nbsp;ځکه چې د موسىٰ په شريعت کښې دا ليکلى دى چې، ”تاسو د غوبل په وخت کښې د غوَيى خولې ته کوَرے مۀ اچوئ.“ ولې خُدائ پاک د غوَيانو فکر کوى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27417, '1 Corinthians 9:10', '1 Corinthians', 9, 10, '&nbsp;يا ولې هغه دا خاص زمونږ دپاره نۀ فرمائى؟ دا حقيقت کښې زمونږ دپاره ليکلے شوى دى ځکه چې څوک قلبه کوى په دې اُميد يې کوى چې څۀ به حاصل کړى او څوک چې غوبل کوى په دې اُميد يې کوى چې په فصل کښې به ورته برخه مِلاو شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27418, '1 Corinthians 9:11', '1 Corinthians', 9, 11, '&nbsp;کۀ مونږ ستاسو په مينځ کښې روحانى تخم وکَرلو نو ولې دا څۀ لويه خبره ده چې مونږ ستاسو د مادى څيزونو فصل وريبو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27419, '1 Corinthians 9:12', '1 Corinthians', 9, 12, '&nbsp;چې د نورو په تاسو دا حق شته نو ولې زمونږ د دې نه زيات نۀ دے څۀ؟ مونږ کله هم دې حق نه کار وانۀ خستو خو مونږ هر څيز برداشت کوُو د دې دپاره چې د مسيح په زېرى کښې څۀ رکاوټ نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27420, '1 Corinthians 9:13', '1 Corinthians', 9, 13, '&nbsp;ولې تاسو نۀ يئ خبر څوک چې د خُدائ د کور خِدمت کوى، نو هغه د خُدائ د کور د نذرانې نه خورى او څوک چې د قربان‌ګاه خِدمتګار دى، نو هغوئ ته د قربانۍ نه حِصه ملاويږى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27421, '1 Corinthians 9:14', '1 Corinthians', 9, 14, '&nbsp;دغه شان مالِک هم حکم کړے دے، څوک چې د زيرى بيانوونکى دى د هغوئ آمدن دې هم د زيرى نه وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27422, '1 Corinthians 9:15', '1 Corinthians', 9, 15, '&nbsp;خو ما خپل د دې حق نه هيڅ فائده وانۀ خستله او نۀ مې دا د دې دپاره وليکل چې زۀ د دې نه فائده واخلم ځکه چې زما دپاره د دې نه مړ کېدل بهتر دى. هيڅوک زما فخر بې‌ځايه کولے نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27423, '1 Corinthians 9:16', '1 Corinthians', 9, 16, '&nbsp;کۀ زۀ زيرے بيانوم نو په دې څۀ فخر نۀ کوم ځکه چې دا زما فرض دى. او افسوس دے په ما، کۀ زۀ زيرے نۀ بيانوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27424, '1 Corinthians 9:17', '1 Corinthians', 9, 17, '&nbsp;ځکه کۀ زۀ دا په خپلې مرضۍ کوم نو اجر زما حق جوړيږى، خو کۀ دا زما په خپلې مرضۍ نۀ وى خو بيا هم خُدائ پاک د دې کار ذمه وارى ما ته راکړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27425, '1 Corinthians 9:18', '1 Corinthians', 9, 18, '&nbsp;نو بيا زما اجر څۀ شے دے؟ صرف دا چې زيرے بيانوم او هغه هم مفت بيان کړم، او د خپل هغه حق نه څۀ فائده وانۀ خلم چې ما ته په زېرى کښې حاصل دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27426, '1 Corinthians 9:19', '1 Corinthians', 9, 19, '&nbsp;اګر کۀ زۀ د ټولو خلقو نه آزاد يم بيا هم ما ځان د ټولو غلام کړو، نو چې نور زيات خلق د مسيح دپاره راولم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27427, '1 Corinthians 9:20', '1 Corinthians', 9, 20, '&nbsp;زۀ د يهوديانو دپاره يهودى شوم دې دپاره چې يهوديان راولم. ما د موسىٰ د شريعت د منونکو د راوستلو دپاره ځان د هغوئ په شريعت کړو، سره د دې چې زۀ د هغوئ د شريعت د لاندې نۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27428, '1 Corinthians 9:21', '1 Corinthians', 9, 21, '&nbsp;ما د بې‌شريعته خلقو دپاره ځان بې‌شريعته جوړ کړو نو چې بې‌شريعته د مسيح دپاره راولم، اګر کۀ زۀ د خُدائ پاک د شريعت نه آزاد نۀ يم بلکې د مسيح په شريعت يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27429, '1 Corinthians 9:22', '1 Corinthians', 9, 22, '&nbsp;زۀ د کمزورو دپاره کمزورے شوم چې کمزورى راولم. ما خپل ځان د مختلفو خلقو په شان جوړ کړو نو چې په څۀ نا څۀ طريقې سره ځينې خلق بچ کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27430, '1 Corinthians 9:23', '1 Corinthians', 9, 23, '&nbsp;زۀ دا هر څۀ د زيرى د خاطره کوم د دې دپاره چې زۀ د هغوئ سره د هغۀ په برکتونو کښې شريک شم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27431, '1 Corinthians 9:24', '1 Corinthians', 9, 24, '&nbsp;ولې تاسو نۀ يئ خبر چې په منډه کښې ټول منډې وهونکى منډې وهى ولې اِنعام يو ګټى؟ نو تاسو هم داسې منډه ووهئ چې وې ګټئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27432, '1 Corinthians 9:25', '1 Corinthians', 9, 25, '&nbsp;هر لوبغاړے په هر څيز کښې سخته پابندى کوى. هغوئ دا د فنا کېدونکى تاج د حاصلولو دپاره کوى، خو مونږ دا د ابدى تاج دپاره کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27433, '1 Corinthians 9:26', '1 Corinthians', 9, 26, '&nbsp;نو زۀ بې‌مقصده منډه نۀ وهم او نۀ زۀ باد په سوکونو وهم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27434, '1 Corinthians 9:27', '1 Corinthians', 9, 27, '&nbsp;بلکې زۀ په خپل بدن تکليف تېروم او خپل غلام يې جوړوم، هسې نه چې زۀ نورو ته زيرے ورکوم او په خپله ترې محرومه شم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27435, '1 Corinthians 10:1', '1 Corinthians', 10, 1, '&nbsp;اے وروڼو او خوېندو، زۀ تاسو د دې نه ناخبره پاتې کېدل نۀ غواړم چې زمونږ پلار نيکونه ټول د وريځې په حفاظت کښې وُو او ټول د بحرِقُلزم سيند نه پورې وتل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27436, '1 Corinthians 10:2', '1 Corinthians', 10, 2, '&nbsp;او ټولو په وريځ او په بحرِقُلزم کښې د موسىٰ بپتسمه واخسته،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27437, '1 Corinthians 10:3', '1 Corinthians', 10, 3, '&nbsp;او ټولو يو شان روحانى خوراک وخوړلو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27438, '1 Corinthians 10:4', '1 Corinthians', 10, 4, '&nbsp;او ټولو يو شان روحانى اوبۀ وڅښلې. ځکه چې هغوئ د هغه روحانى ګټ نه اوبۀ وڅښلې کوم چې د هغوئ سره روان وو، او هغه ګټ مسيح وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27439, '1 Corinthians 10:5', '1 Corinthians', 10, 5, '&nbsp;خو په هغوئ کښې د ډېرو نه خُدائ پاک راضى نۀ وو نو ځکه د هغوئ لاشونه په بيابان کښې خوارۀ وارۀ شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27440, '1 Corinthians 10:6', '1 Corinthians', 10, 6, '&nbsp;اوس دا خبرې زمونږ دپاره يو مثال شو نو چې بيا مونږ د خرابو څيزونو خواهش ونۀ کړو لکه څنګه چې هغوئ کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27441, '1 Corinthians 10:7', '1 Corinthians', 10, 7, '&nbsp;تاسو بُت پرست مۀ جوړېږئ لکه چې په هغوئ کښې ځينې شوى وُو، لکه څنګه چې ليکلى دى چې، ”هغه خلق د خوړلو او څښلو دپاره کښېناستل او بيا هغوئ پاڅېدل، د مستۍ او عياشۍ سره ګډېدل.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27442, '1 Corinthians 10:8', '1 Corinthians', 10, 8, '&nbsp;مونږ دې جنسى حرامکارى ونۀ کړُو لکه څنګه چې په هغوئ کښې ځينو کړې وه او په يوه ورځ کښې درويشت زره هلاک شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27443, '1 Corinthians 10:9', '1 Corinthians', 10, 9, '&nbsp;مونږ دې د مسيح آزمېښت ونۀ کړُو لکه څنګه چې په هغوئ کښې ځينو کړے وو او بيا مارانو هلاک کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27444, '1 Corinthians 10:10', '1 Corinthians', 10, 10, '&nbsp;او تاسو شکايت ونۀ کړئ لکه څنګه چې په هغوئ کښې ځينو کړے وو او بيا د هلاکت فرښتې هغوئ هلاک کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27445, '1 Corinthians 10:11', '1 Corinthians', 10, 11, '&nbsp;په هغوئ دا خبرې زمونږ د عبرت دپاره راغلې وې او زمونږ د آخرى زمانې خلقو ته د نصيحت دپاره وليکلے شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27446, '1 Corinthians 10:12', '1 Corinthians', 10, 12, '&nbsp;نو کۀ ستا خيال وى چې تۀ مضبوط ولاړ يې خو احتياط کوه چې راپرې نۀ وځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27447, '1 Corinthians 10:13', '1 Corinthians', 10, 13, '&nbsp;تاسو په څۀ داسې آزمېښت کښې نۀ يئ پرېوتلى چې هغه د نورو انسانانو نه مختلف وى، نو خُدائ پاک وفادار دے او هغه به تاسو ستاسو د برداشت نه په زيات آزمېښت کښې نۀ اچوى، بلکې د آزمېښت په وخت کښې به هغه تاسو ته د وتلو لار هم پېدا کړى چې يې تاسو برداشت کولے شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27448, '1 Corinthians 10:14', '1 Corinthians', 10, 14, '&nbsp;نو په دې وجه زما خوږو ملګرو، د بُت پرستۍ نه وتښتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27449, '1 Corinthians 10:15', '1 Corinthians', 10, 15, '&nbsp;تاسو په خپله پوهيږى څۀ چې زۀ وايم تاسو د هغې په خپله جاج واخلئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27450, '1 Corinthians 10:16', '1 Corinthians', 10, 16, '&nbsp;کله چې د عشاء ربانى په وخت کښې مونږ هغه پيالۍ ته برکت ورکوو، ولې هغه د مسيح په وينه کښې شراکت نۀ دے څۀ؟ هغه روټۍ چې مونږ يې ماتوو، ولې هغه د مسيح د بدن شراکت نۀ دے څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27451, '1 Corinthians 10:17', '1 Corinthians', 10, 17, '&nbsp;کۀ څۀ هم چې مونږ ډېر يُو خو په شريکه د يوې روټۍ نه خورو او په دې دا څرګنده وُو چې مونږ يو بدن يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27452, '1 Corinthians 10:18', '1 Corinthians', 10, 18, '&nbsp;بنى اِسرائيلو ته وګورئ. ولې هغوئ د قربانيانو خوړلو دپاره په قربان‌ګاه کښې شريکيږى نه څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27453, '1 Corinthians 10:19', '1 Corinthians', 10, 19, '&nbsp;ولې زما مطلب دا دے چې ګنې د بُت د قربانۍ څۀ حيثيت وى؟ او يا د بُت څۀ حيثيت شته دے؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27454, '1 Corinthians 10:20', '1 Corinthians', 10, 20, '&nbsp;نه، زۀ دا وايم چې کومې قربانۍ چې غېر‌يهوديان کوى، هغوئ پيريانو ته قربانى کوى، خُدائ پاک ته يې نۀ کوى، او زۀ دا نۀ غواړم چې تاسو د پيريانو سره شريک شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27455, '1 Corinthians 10:21', '1 Corinthians', 10, 21, '&nbsp;تاسو د مالِک د پيالۍ نه او د پيريانو د پيالۍ نه نۀ شئ څښلے، تاسو د مالِک په دسترخوان او د پيريانو په دسترخوان کښې نۀ شئ شريک کېدے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27456, '1 Corinthians 10:22', '1 Corinthians', 10, 22, '&nbsp;يا ولې مونږ د مالِک غېرت کښې راولو څۀ؟ ولې مونږ د هغۀ نه زورَور يُو څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27457, '1 Corinthians 10:23', '1 Corinthians', 10, 23, '&nbsp;هر څۀ روا دى، خو هر څۀ فائده مند نۀ دى. هر څۀ روا دى خو هر څۀ ترقى نۀ ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27458, '1 Corinthians 10:24', '1 Corinthians', 10, 24, '&nbsp;تاسو خپلې فائدې مۀ لټوئ بلکې د نورو هم لټوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27459, '1 Corinthians 10:25', '1 Corinthians', 10, 25, '&nbsp;څۀ چې د قصاب په دوکان خرڅيږى هغه خورئ او د ضمير په خاطر سوال مۀ پورته کوئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27460, '1 Corinthians 10:26', '1 Corinthians', 10, 26, '&nbsp;ځکه ”دا دُنيا د مالِک خُدائ ده او هر څۀ چې په دې کښې دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27461, '1 Corinthians 10:27', '1 Corinthians', 10, 27, '&nbsp;کۀ څوک غېر ايماندار تاسو ته د روټۍ دعوت وکړى او تاسو په تلو راضى يئ، نو هر څۀ چې درته وړاندې کېږدى هغه خورئ او په خپل ضمير کښې سوال مۀ راولئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27462, '1 Corinthians 10:28', '1 Corinthians', 10, 28, '&nbsp;خو کۀ تاسو ته څوک ووائى چې، ”دا بُت ته د قربانۍ غوښه ده،“ نو د هغۀ د ضمير د خاطره هغه مۀ خوره.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27463, '1 Corinthians 10:29', '1 Corinthians', 10, 29, '&nbsp;زما مطلب د نورو ضمير دے ستاسو نۀ دے. ځکه چې د بل چا ضمير زما د آزادۍ فېصله ولې کوى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27464, '1 Corinthians 10:30', '1 Corinthians', 10, 30, '&nbsp;کۀ زۀ په کښې په شُکر ګزارۍ شريک شم، نو چې په کوم څيز زۀ شُکر وباسم نو بيا د هغې په سبب زۀ ولې ملامت شم؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27465, '1 Corinthians 10:31', '1 Corinthians', 10, 31, '&nbsp;نو بيا چې تاسو څۀ خورئ يا څښئ يا چې څۀ کوئ، هغه هر څۀ د خُدائ پاک د لويئ دپاره کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27466, '1 Corinthians 10:32', '1 Corinthians', 10, 32, '&nbsp;د يهوديانو او يونانيانو او د خُدائ پاک د جماعت دپاره د تيندک سبب مۀ جوړېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27467, '1 Corinthians 10:33', '1 Corinthians', 10, 33, '&nbsp;څنګه چې زۀ په خپل هر کار کښې د هر چا د خوشحالولو کوشش کوم نو دا زۀ د خپلې فائدې دپاره نۀ کوم بلکې د نورو ډېرو دپاره يې کوم د دې دپاره چې هغوئ پرې خلاصون بيا مومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27468, '1 Corinthians 11:1', '1 Corinthians', 11, 1, '&nbsp;تاسو زما په نقش قدم شئ لکه څنګه چې زۀ د مسيح په نقش قدم روان يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27469, '1 Corinthians 11:2', '1 Corinthians', 11, 2, '&nbsp;زۀ ستاسو تعريف کوم ځکه چې تاسو په هره خبره کښې ما يادوئ، او څنګه چې ما تاسو ته روايتونه در وسپارل تاسو هغه هم هغه شان برقرار ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27470, '1 Corinthians 11:3', '1 Corinthians', 11, 3, '&nbsp;خو زۀ غواړم چې تاسو پوهه شئ چې د هر سړى سر مسيح دے، او خاوند د خپلې ښځې سر دے، او د مسيح سر خُدائ پاک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27471, '1 Corinthians 11:4', '1 Corinthians', 11, 4, '&nbsp;کوم سړے چې په پټ سر دُعا يا نبوت کوى هغه د مسيح بې‌عزتى کوى څوک چې د هغۀ سر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27472, '1 Corinthians 11:5', '1 Corinthians', 11, 5, '&nbsp;خو کومه ښځه چې سر توره دُعا يا نبوت کوى نو هغه د خپل خاوند بې‌عزتى کوى ځکه چې هغه د سر خرئيلې په شان ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27473, '1 Corinthians 11:6', '1 Corinthians', 11, 6, '&nbsp;ځکه کۀ يوه ښځه لوپټه نۀ په سره وى نو هغه دې وېښتۀ هم کټ کړى. خو کۀ د ښځې دپاره وېښتۀ کټ کول او سر خرئيل د شرم خبره وى نو لوپټه دې په سره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
