(27475, '1 Corinthians 11:8', '1 Corinthians', 11, 8, '&nbsp;ځکه چې سړے د ښځې نه نۀ دے پېدا شوے بلکې ښځه د سړى نه پېدا شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27476, '1 Corinthians 11:9', '1 Corinthians', 11, 9, '&nbsp;سړے د ښځې د خاطره نۀ دے پېدا شوے بلکې ښځه د سړى د خاطره پېدا شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27477, '1 Corinthians 11:10', '1 Corinthians', 11, 10, '&nbsp;نو د فرښتو د ليدو په سبب ښځې له په کار دى چې په خپل سر د اختيار نښه کېږدى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27478, '1 Corinthians 11:11', '1 Corinthians', 11, 11, '&nbsp;خو په مالِک کښې ښځه د سړى نه غېر آزاده نۀ ده او يا سړے د ښځې نه غېر آزاد نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27479, '1 Corinthians 11:12', '1 Corinthians', 11, 12, '&nbsp;ځکه څنګه چې ښځه د سړى نه پېدا شوې ده نو سړے هم د ښځې په وسيله پېدا شوے دے، خو ټول څيزونه د خُدائ پاک د طرفه دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27480, '1 Corinthians 11:13', '1 Corinthians', 11, 13, '&nbsp;تاسو په خپله اِنصاف وکړئ چې ولې ښځې ته مناسب دى چې په سر توره خُدائ پاک ته دُعا وکړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
