(27482, '1 Corinthians 11:15', '1 Corinthians', 11, 15, '&nbsp;خو کۀ د ښځې اوږدۀ وېښتۀ وى نو دا د هغې ښُکلا ده، ځکه چې وېښتۀ هغې ته د پردې دپاره ورکړے شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27483, '1 Corinthians 11:16', '1 Corinthians', 11, 16, '&nbsp;خو کۀ څوک په دې خبره بحث کوى نو نۀ دا زمونږ او نۀ د خُدائ پاک د جماعتونو دستور دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27484, '1 Corinthians 11:17', '1 Corinthians', 11, 17, '&nbsp;خو اوس په دې هداياتو کښې زۀ ستاسو ستائينه نۀ کوم ځکه چې ستاسو رايوځائ کېدل د فائدې نه بلکې د نقصان باعث جوړيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
