(27486, '1 Corinthians 11:19', '1 Corinthians', 11, 19, '&nbsp;ځکه چې په تاسو کښې ډله بازى ضرورى ده صرف د دې دپاره چې دا ښکاره شى چې په تاسو کښې څوک رښتينى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
