(27488, '1 Corinthians 11:21', '1 Corinthians', 11, 21, '&nbsp;ځکه چې کله د خوراک وخت راشى نو تاسو هر يو خپل خوراک کوئ، او څوک په کښې نهر او څوک نشه پاتې شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27489, '1 Corinthians 11:22', '1 Corinthians', 11, 22, '&nbsp;نو ولې د خوراک څښاک دپاره ستاسو خپل کورونه نشته څۀ؟ يا ولې تاسو د خُدائ پاک جماعت سپکوئ او هغوئ شرموئ چې چا سره څۀ نشته؟ زۀ تاسو ته څۀ ووايم؟ ولې زۀ ستاسو تعريف وکړم؟ په دې عمل زۀ ستاسو تعريف نۀ کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27490, '1 Corinthians 11:23', '1 Corinthians', 11, 23, '&nbsp;ځکه چې کومې خبرې ما تاسو ته حواله کړې نو هغه ما د مالِک نه حاصلې کړې دى، چې په کومه شپه د مالِک عيسىٰ مُخبرى وشوه روټۍ يې راواخسته،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27491, '1 Corinthians 11:24', '1 Corinthians', 11, 24, '&nbsp;او کله چې هغۀ پرې شُکر وکړو نو ماته يې کړه او وې فرمائيل چې، ”دا زما بدن دے چې ستاسو دپاره دے. زما په ياد کښې دغه شان کوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27492, '1 Corinthians 11:25', '1 Corinthians', 11, 25, '&nbsp;هم دغه شان هغۀ د روټۍ نه پس پيالۍ واخسته او وې فرمائيل چې، ”دا پيالۍ زما په وينه کښې د خُدائ پاک او انسانانو په مينځ کښې نوے لوظ دے. هر کله چې دا څښئ نو زما په ياد کښې يې څښئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27493, '1 Corinthians 11:26', '1 Corinthians', 11, 26, '&nbsp;نو هر کله چې تاسو دا روټۍ خورئ او دا پياله څښئ نو تاسو د مالِک د مرګ اعلان کوئ ترڅو چې هغه رانۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
