(27495, '1 Corinthians 11:28', '1 Corinthians', 11, 28, '&nbsp;د عشائى ربانى روټۍ خوړلو او پيالۍ څښلو نه اول خپل ځان وآزمائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27496, '1 Corinthians 11:29', '1 Corinthians', 11, 29, '&nbsp;نو ځکه چې څوک په خوراک څښاک کښې د مالِک د بدن خيال ونۀ ساتى، نو هغه به په هغه خوړلو څښلو سزا بيا مومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
